/**
 * KS-1175 — accept and anchor Platform-S's non-PII actor + organisation identity block beside identityCommitment.
 *
 * Contract under test (KS-1175; PS-869 ruling 2026-09-16; Stuart's wire shape 2026-09-16T10:36:32Z): POST /api/anchors
 * accepts a TOP-LEVEL `identity` object — actorDid, actorLevel, actorSource, actorVerified, orgDid, orgTrust,
 * orgVerified, identityCommitment — all optional, shape-validated (400 on a malformed value, never silently anchored),
 * unknown keys inside it stripped (KS-240). The seven fields are anchored FLAT under `secuura`, whitelisted BY NAME
 * (no spread of caller input), beside documentType / occurredAt / identityCommitment.
 *
 * Every cell here is pure: zod and the payload builder. No port, no DB, no chain.
 *
 * Red-first: R1–R4 and R6 are RED at develop dc061f2bb (the `identity` object is undeclared there, so zod strips it
 * and nothing survives to the payload); R5 and R7 are CONTROLS, green before and after — they are the two guards the
 * widening consciously keeps (strip-by-default, whitelist-by-name).
 */

import { describe, it, expect } from 'vitest';

import { anchorDocumentSchema, buildFlatAnchorMetadataPayload } from '../anchorSchema';

const BASE_BODY = {
  documentId: 'doc-1777346021120-1e528170',
  contentHash: 'a1b2c3d4e5f60718293a4b5c6d7e8f901a2b3c4d5e6f70819203a4b5c6d7e8f9',
};

/** Stuart's example block, verbatim in shape (PS-870): every field present, the commitment in layout-2 purpose. */
const COMMITMENT = `identity-commitment-l2.v1:${'b'.repeat(64)}`;
const FULL_IDENTITY = {
  actorDid: 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK',
  actorLevel: 2,
  actorSource: 'stripe',
  actorVerified: true,
  orgDid: 'did:web:acme.example',
  orgTrust: 'domain',
  orgVerified: true,
  identityCommitment: COMMITMENT,
} as const;

const SEVEN = ['actorDid', 'actorLevel', 'actorSource', 'actorVerified', 'orgDid', 'orgTrust', 'orgVerified'] as const;

describe('anchorDocumentSchema — KS-1175 top-level identity block (R1: the strip)', () => {
  it('accepts the full identity block and keeps it — nothing S sends is silently dropped', () => {
    const result = anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: FULL_IDENTITY });
    expect(result.success).toBe(true);
    // At the tip `identity` is undeclared → stripped → undefined. RED by assertion, not by throw.
    expect(result.success && result.data.identity).toEqual(FULL_IDENTITY);
  });

  it('keeps a partial block exactly as sent — absent fields stay absent (S omits, never nulls)', () => {
    const partial = { actorDid: FULL_IDENTITY.actorDid, actorLevel: 1, actorVerified: false };
    const result = anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: partial });
    expect(result.success).toBe(true);
    expect(result.success && result.data.identity).toEqual(partial);
  });

  it('still accepts K-internal calls that send no identity at all (block stays optional)', () => {
    const result = anchorDocumentSchema.safeParse(BASE_BODY);
    expect(result.success).toBe(true);
    expect(result.success && 'identity' in result.data && result.data.identity !== undefined).toBe(false);
  });
});

describe('buildFlatAnchorMetadataPayload — KS-1175 the seven anchored flat under secuura (R2: the whitelist)', () => {
  it('carries the seven by name with the input values, beside documentType / occurredAt / identityCommitment', () => {
    const parsed = anchorDocumentSchema.parse({
      ...BASE_BODY,
      metadata: { documentType: 'sign', timestamp: '2026-09-16T10:36:32Z' },
      identity: FULL_IDENTITY,
    });
    const sec = buildFlatAnchorMetadataPayload(parsed, 'preview').secuura;
    for (const k of SEVEN) expect(sec[k], k).toEqual(FULL_IDENTITY[k]);
    expect(sec.documentType).toBe('sign');
    expect(sec.occurredAt).toBe('2026-09-16T10:36:32.000Z');
    expect(sec.identityCommitment).toBe(COMMITMENT);
  });

  it.each(SEVEN)('anchors %s on its own when it is the only identity field sent (and no other identity key appears)', (field) => {
    const parsed = anchorDocumentSchema.parse({ ...BASE_BODY, identity: { [field]: FULL_IDENTITY[field] } });
    const sec = buildFlatAnchorMetadataPayload(parsed, 'preview').secuura;
    expect(sec[field]).toEqual(FULL_IDENTITY[field]);
    for (const other of SEVEN) if (other !== field) expect(other in sec, other).toBe(false);
  });

  it('anchors a FALSE boolean (actorVerified: false) — a falsy value must not be dropped by a truthiness spread', () => {
    const parsed = anchorDocumentSchema.parse({ ...BASE_BODY, identity: { actorVerified: false, orgVerified: false } });
    const sec = buildFlatAnchorMetadataPayload(parsed, 'preview').secuura;
    expect(sec.actorVerified).toBe(false);
    expect(sec.orgVerified).toBe(false);
  });

  it('omits every identity key when no identity block is sent', () => {
    const sec = buildFlatAnchorMetadataPayload(anchorDocumentSchema.parse(BASE_BODY), 'preview').secuura;
    for (const k of SEVEN) expect(k in sec, k).toBe(false);
  });
});

describe('anchorDocumentSchema — KS-1175 one arm per field (R3: malformed → 400, valid → survives)', () => {
  // Each arm is ONE conjunct: the malformed value fails; the positive control flips ONLY that field to a valid value
  // and asserts the field SURVIVES the parse — which is what makes each arm red at the tip, where the whole block is
  // stripped and "nothing was validated" looks like "everything passed".
  const arm = (field: string, bad: unknown, good: unknown) => {
    it(`${field}: rejects ${JSON.stringify(bad)} (400 class), accepts ${JSON.stringify(good)} and keeps it`, () => {
      expect(anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: { [field]: bad } }).success).toBe(false);
      const ok = anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: { [field]: good } });
      expect(ok.success).toBe(true);
      expect(ok.success && (ok.data.identity as Record<string, unknown>)[field]).toEqual(good);
    });
  };
  arm('actorLevel', 4, 3);
  arm('actorLevel', 0, 1);
  arm('actorLevel', '2', 2); // a numeric STRING is not an integer
  arm('actorLevel', 2.5, 2);
  arm('actorSource', 'google', 'entra-verified-id');
  arm('actorDid', 'foo', 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK');
  arm('actorDid', `did:web:${'a'.repeat(505)}`, `did:web:${'a'.repeat(504)}`); // 513 vs 512 chars — the max() bound
  arm('actorDid', 'did:ethr:0xabc', 'did:web:acme.example'); // method outside key|web
  arm('actorVerified', 'yes', true);
  arm('actorVerified', 1, false);
  arm('orgDid', 'did:x:1', 'did:web:acme.example');
  arm('orgTrust', 'high', 'kyc');
  arm('orgTrust', 'Domain', 'domain'); // enums are exact-case
  arm('orgVerified', 1, true);
  arm('identityCommitment', `identity-commitment-l2.v1:${'B'.repeat(64)}`, COMMITMENT); // uppercase hex — KS-721's rule
  arm('identityCommitment', 'a'.repeat(64), COMMITMENT); // bare hash, no key version

  it.each(SEVEN)('%s: null is a caller error (400), never silently anchored', (field) => {
    expect(anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: { [field]: null } }).success).toBe(false);
  });
  it.each(SEVEN)('%s: "" is a caller error (400), never silently anchored', (field) => {
    expect(anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: { [field]: '' } }).success).toBe(false);
  });
  it('the whole block must be an object — a string or array where S sends an object is 400', () => {
    expect(anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: 'did:key:abc' }).success).toBe(false);
    expect(anchorDocumentSchema.safeParse({ ...BASE_BODY, identity: [FULL_IDENTITY] }).success).toBe(false);
  });
});

describe('anchorDocumentSchema — KS-1175 the duplicate commitment (R4: DECIDE 2)', () => {
  const OTHER = `identity-commitment-l2.v1:${'c'.repeat(64)}`;

  it('both present and EQUAL → exactly one identityCommitment key in the payload, at its existing position', () => {
    const parsed = anchorDocumentSchema.parse({
      ...BASE_BODY,
      metadata: { identityCommitment: COMMITMENT },
      identity: { identityCommitment: COMMITMENT },
    });
    const sec = buildFlatAnchorMetadataPayload(parsed, 'preview').secuura;
    expect(sec.identityCommitment).toBe(COMMITMENT);
    expect(Object.keys(sec).filter((k) => k === 'identityCommitment')).toHaveLength(1);
    expect(JSON.stringify(sec).split(COMMITMENT)).toHaveLength(2); // the value appears exactly once
  });

  it('both present and DIFFERENT → 400 (two values of one commitment are two anchors), at path identity.identityCommitment', () => {
    const result = anchorDocumentSchema.safeParse({
      ...BASE_BODY,
      metadata: { identityCommitment: COMMITMENT },
      identity: { identityCommitment: OTHER },
    });
    expect(result.success).toBe(false);
    expect(!result.success && result.error.issues.some((i) => i.path.join('.') === 'identity.identityCommitment')).toBe(true);
  });

  it('only identity.identityCommitment → anchored under the existing identityCommitment key', () => {
    const parsed = anchorDocumentSchema.parse({ ...BASE_BODY, identity: { identityCommitment: COMMITMENT } });
    const sec = buildFlatAnchorMetadataPayload(parsed, 'preview').secuura;
    expect(sec.identityCommitment).toBe(COMMITMENT);
  });

  it('only metadata.identityCommitment → unchanged from KS-721 (control)', () => {
    const parsed = anchorDocumentSchema.parse({ ...BASE_BODY, metadata: { identityCommitment: COMMITMENT } });
    expect(buildFlatAnchorMetadataPayload(parsed, 'preview').secuura.identityCommitment).toBe(COMMITMENT);
  });
});

describe('KS-1175 negative controls — the two guards the widening keeps (R5, R7; green before AND after)', () => {
  it('R5: an unknown key inside identity is stripped and its free text never reaches the payload', () => {
    const result = anchorDocumentSchema.safeParse({
      ...BASE_BODY,
      identity: { ...FULL_IDENTITY, actorName: 'Jane Doe', actorEmail: 'jane@org.example' },
    } as Record<string, unknown>);
    expect(result.success).toBe(true);
    const identity = (result.success ? result.data.identity : undefined) as Record<string, unknown> | undefined;
    expect(identity?.actorName).toBeUndefined();
    expect(identity?.actorEmail).toBeUndefined();
    const flat = JSON.stringify(buildFlatAnchorMetadataPayload(anchorDocumentSchema.parse({
      ...BASE_BODY,
      identity: { ...FULL_IDENTITY, actorName: 'Jane Doe', actorEmail: 'jane@org.example' },
    } as Record<string, unknown>), 'preview'));
    expect(flat).not.toContain('Jane Doe');
    expect(flat).not.toContain('jane@org.example');
    expect(flat).not.toContain('actorName');
  });

  it('R7: with identity present, issuerName and the onBehalfOf triplet are STILL excluded (KS-240 / KS-480 §6 extended)', () => {
    const flat = JSON.stringify(buildFlatAnchorMetadataPayload(anchorDocumentSchema.parse({
      ...BASE_BODY,
      issuerName: 'Acme Corp',
      onBehalfOf: { email: 'jane@org.example', displayName: 'Jane Doe', externalRef: 'person-guid-1' },
      identity: { ...FULL_IDENTITY, actorName: 'Jane Doe' },
    } as Record<string, unknown>), 'preview'));
    for (const s of ['Acme Corp', 'onBehalfOf', 'jane@org.example', 'Jane Doe', 'person-guid-1', 'actorName']) {
      expect(flat, s).not.toContain(s);
    }
  });

  it('the logical payload has no array-valued key — the KS-1284 chain reader joins any all-string array, so this must stay true', () => {
    // A guard that can fail: the day a whitelisted field becomes an array, fromCardanoMetadatum's join rule turns
    // ambiguous and this cell is the one that says so.
    const parsed = anchorDocumentSchema.parse({
      ...BASE_BODY,
      environment: 'test',
      issuerOrgId: 'org-ks1175',
      certId: 'doc-1758369000-ks1175certid',
      metadata: { documentType: 'sign', timestamp: '2026-09-16T10:36:32Z', identityCommitment: COMMITMENT },
      identity: FULL_IDENTITY,
    });
    const sec = buildFlatAnchorMetadataPayload(parsed, 'preview').secuura;
    for (const [k, v] of Object.entries(sec)) expect(Array.isArray(v), k).toBe(false);
  });
});
